import { Excalidraw } from "@excalidraw/excalidraw";
import type {
  AppState,
  BinaryFiles,
  ExcalidrawElement,
  ExcalidrawImperativeAPI,
} from "@excalidraw/excalidraw/types";
import { useCallback, useEffect, useRef, useState } from "react";

type ExcalidrawPayload = {
  elements: ExcalidrawElement[];
  appState: Partial<AppState>;
  files: BinaryFiles;
};

declare global {
  interface Window {
    dddApplet: {
      getDiagram: () => Promise<{ path: string; content: string }>;
      onDiagramUpdated: (callback: (content: string) => void) => () => void;
    };
  }
}

function parsePayload(raw: string): ExcalidrawPayload {
  const parsed = JSON.parse(raw) as {
    elements?: ExcalidrawElement[];
    appState?: Partial<AppState>;
    files?: BinaryFiles;
  };

  return {
    elements: parsed.elements ?? [],
    appState: parsed.appState ?? {},
    files: parsed.files ?? {},
  };
}

function sceneFingerprint(
  elements: readonly ExcalidrawElement[],
  files: BinaryFiles
): string {
  return JSON.stringify({ elements, files });
}

export function ViewerApp(): JSX.Element {
  const [payload, setPayload] = useState<ExcalidrawPayload | null>(null);
  const [diagramPath, setDiagramPath] = useState("");
  const apiRef = useRef<ExcalidrawImperativeAPI | null>(null);
  const lastFingerprint = useRef("");
  const latestAppState = useRef<Partial<AppState>>({});

  const applyDiagram = useCallback((raw: string, pathLabel: string) => {
    const parsed = parsePayload(raw);
    const fingerprint = sceneFingerprint(parsed.elements, parsed.files);
    if (fingerprint === lastFingerprint.current) {
      return;
    }
    lastFingerprint.current = fingerprint;

    const api = apiRef.current;
    if (api) {
      api.updateScene({
        elements: parsed.elements,
        files: parsed.files,
        appState: {
          ...parsed.appState,
          viewModeEnabled: true,
          scrollX: latestAppState.current.scrollX ?? parsed.appState.scrollX,
          scrollY: latestAppState.current.scrollY ?? parsed.appState.scrollY,
          zoom: latestAppState.current.zoom ?? parsed.appState.zoom,
        },
      });
    } else {
      setPayload(parsed);
    }
    setDiagramPath(pathLabel);
  }, []);

  useEffect(() => {
    const applet = window.dddApplet;
    if (!applet) {
      setDiagramPath("error: applet bridge not loaded (preload failed)");
      return;
    }

    void applet.getDiagram().then(({ path, content }) => {
      applyDiagram(content, path);
    });

    return applet.onDiagramUpdated((content) => {
      void applet.getDiagram().then(({ path }) => {
        applyDiagram(content, path);
      });
    });
  }, [applyDiagram]);

  if (!payload) {
    return (
      <div
        style={{
          alignItems: "center",
          color: "#495057",
          display: "flex",
          fontFamily: "system-ui, sans-serif",
          fontSize: 14,
          height: "100%",
          justifyContent: "center",
          width: "100%",
        }}
      >
        Loading diagram…
      </div>
    );
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100vh",
        width: "100vw",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          background: "#1e1e1e",
          color: "#e9ecef",
          flexShrink: 0,
          fontFamily: "system-ui, sans-serif",
          fontSize: 12,
          padding: "6px 12px",
          WebkitAppRegion: "drag",
        }}
      >
        Design Drive Development — {diagramPath} (live reload)
      </div>
      <div style={{ flex: 1, minHeight: 0, position: "relative" }}>
        <Excalidraw
          excalidrawAPI={(api) => {
            apiRef.current = api;
          }}
          initialData={{
            elements: payload.elements,
            appState: {
              ...payload.appState,
              viewModeEnabled: true,
              width: window.innerWidth,
              height: Math.max(window.innerHeight - 32, 400),
            },
            files: payload.files,
          }}
          onChange={(_elements, appState) => {
            latestAppState.current = appState;
          }}
          UIOptions={{
            canvasActions: {
              loadScene: false,
              saveToActiveFile: false,
              export: { saveFileToDisk: false },
            },
          }}
        />
      </div>
    </div>
  );
}
